class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_beautiful_upto(n):
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            length = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, started, prod, summ):
                if pos == length:
                    if not started:
                        return 0
                    if summ == 0:
                        return 0
                    return 1 if prod % summ == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)

                    if not new_started:
                        total += dp(pos + 1, new_tight, new_started, 1, 0)
                    else:
                        new_prod = prod * d if d != 0 else prod
                        new_summ = summ + d
                        total += dp(pos + 1, new_tight, new_started, new_prod, new_summ)

                return total

            return dp(0, True, False, 1, 0)

        return count_beautiful_upto(r) - count_beautiful_upto(l - 1)

import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:1+N]))
    if N % 2 == 1:
        # Fennec's turn on odd index
        total = sum(A)
        if total % 2 == 1:
            print("Fennec")
        else:
            print("Snuke")
    else:
        # Snuke's turn on even index
        total = sum(A)
        if total % 2 == 0:
            print("Fennec")
        else:
            print("Snuke")

if __name__ == "__main__":
    main()

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        total = 0
        total += sum(1 for c in s if c != '0')
        if n <= 1:
            return total
        for i in range(n):
            num = 0
            for j in range(i, n):
                num = num * 10 + int(s[j])
                if s[j] == '0':
                    continue
                d = int(s[j])
                if num % d == 0:
                    total += 1
        return total

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = float('inf')
        # dp[i] will store (min_ops, lexicographically smallest string) for caption[i:]
        # We'll use dynamic programming with memoization.
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def solve(i):
            # Returns (min_ops, best_string) for substring caption[i:]
            if i >= n:
                return (0, "")
            if n - i < 3:
                return (INF, None)

            best_ops = INF
            best_str = None

            # Try all possible characters c from 'a' to 'z' for the first position
            # But we need to ensure that the group we form has at least 3 chars
            # and the rest of the string forms a good caption
            for c in range(26):
                char = chr(ord('a') + c)
                cost = abs(ord(caption[i]) - ord(char))

                # Find the length of the group: from i, how many characters we can change to char
                # Actually, we are choosing to make a group of some length k >= 3
                # We need to consider groups of length 3, 4, 5, ...
                # The maximum possible group length is n - i

                # But we can also consider not just changing but also the case where
                # we extend as far as possible. Actually, the key insight is:
                # We can change any character to any other character with cost equal to
                # the absolute difference. So for position i, we can change it to char
                # with cost |caption[i] - char|.

                # After setting caption[i] to char, we need to set the next k-1 characters
                # also to char (or possibly we skip some, but skipping would break the group).
                # Actually, we are forming a group of consecutive identical characters.
                # So we need positions i, i+1, ..., i+k-1 to all be char.
                # And position i+k must start a new group (or be end of string).

                # So we try all k from 3 to (n - i)
                for k in range(3, n - i + 1):
                    # Calculate cost to set positions i..i+k-1 to char
                    group_cost = 0
                    for j in range(i, i + k):
                        group_cost += abs(ord(caption[j]) - ord(char))
                        if group_cost >= best_ops:
                            break
                    else:
                        # Check if remaining part can form a good caption
                        if i + k == n:
                            # End of string
                            if group_cost < best_ops:
                                best_ops = group_cost
                                best_str = char * k
                            elif group_cost == best_ops:
                                candidate = char * k
                                if candidate < best_str:
                                    best_str = candidate
                        else:
                            # Need to solve for i+k
                            sub_ops, sub_str = solve(i + k)
                            if sub_ops != INF:
                                total = group_cost + sub_ops
                                if total < best_ops:
                                    best_ops = total
                                    best_str = char * k + sub_str
                                elif total == best_ops:
                                    candidate = char * k + sub_str
                                    if candidate < best_str:
                                        best_str = candidate

            return (best_ops, best_str)

        ops, result = solve(0)
        if ops == INF:
            return ""
        return result

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            return True

        # Bucket nodes by their value
        buckets = [[] for _ in range(threshold + 1)]
        for idx, v in enumerate(nums):
            if v <= threshold:
                for m in range(v, threshold + 1, v):
                    buckets[m].append(idx)

        # Connect nodes that share a bucket (meaning lcm <= threshold)
        for bucket in buckets:
            if len(bucket) > 1:
                first = bucket[0]
                for other in bucket[1:]:
                    union(first, other)

        # Count distinct roots among all nodes
        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)
